# -*- coding: utf-8 -*-
# AUTO-GENERATED UNIT TESTS - NEONROGUE
import unittest
from engine.entities import Player, Enemy, Vendor
from engine.world import World
from engine.generator import MapGenerator
from engine.combat import Combat
from engine.hacking import HackingGame
from data.items import WEAPONS_DATABASE, ARMOR_DATABASE, CONSUMABLES_DATABASE

class TestGameCore(unittest.TestCase):
    def setUp(self):
        self.player = Player("TestAgent")
        self.enemy = Enemy("TestDrone", 50, 50, 1, 5, 10, 10)

    def test_player_initialization(self):
        self.assertEqual(self.player.name, "TestAgent")
        self.assertEqual(self.player.level, 1)
        self.assertEqual(self.player.hp, 100)
        self.assertEqual(self.player.max_hp, 100)

    def test_player_gain_xp(self):
        leveled = self.player.gain_xp(100)
        self.assertTrue(leveled)
        self.assertEqual(self.player.level, 2)

    def test_enemy_initialization(self):
        self.assertEqual(self.enemy.name, "TestDrone")
        self.assertTrue(self.enemy.is_alive)

    def test_enemy_take_damage(self):
        self.enemy.take_damage(20)
        self.assertEqual(self.enemy.hp, 30)

    def test_generator(self):
        gen = MapGenerator()
        lvl = gen.generate_level(1)
        self.assertIn("grid", lvl)
        self.assertIn("enemies", lvl)

